c='p12';B='MẠNG 4'
def box(x,y,w,h,t,f='#BBDEFB',s='#1565C0',fs=20):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="8" fill="{f}" stroke="{s}" stroke-width="3"/><text x="{x+w/2}" y="{y+h/2+7}" text-anchor="middle" font-size="{fs}" font-weight="800" fill="#0B2545" font-family="sans-serif">{t}</text>'
def ln(x1,y1,x2,y2,col='#0B2545',w=3): return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{col}" stroke-width="{w}"/>'
def svg(h,b): return f'<svg viewBox="0 0 520 {h}" style="width:100%">{b}</svg>'
S=[]
S.append(TITLE('TIN HỌC · MẠNG MÁY TÍNH 4','CHIA SẺ TÀI NGUYÊN<br>VÀ AN TOÀN MẠNG','Chia sẻ tệp, máy in, đám mây; mối đe doạ mạng; tường lửa, mã hoá, VPN; ứng xử an toàn trên mạng.',['chia sẻ','tường lửa','mã hoá','VPN','phishing']))
S.append(goals(c,B,['Nêu cách <b>chia sẻ tài nguyên</b> trong LAN và qua đám mây.','Kể tên các <b>mối đe doạ</b> an toàn mạng.','Giải thích vai trò <b>tường lửa, mã hoá, VPN</b>.','Nhận biết <b>phishing</b> và thực hành ứng xử an toàn.','Phân biệt <b>mã hoá đối xứng và bất đối xứng</b>.'],['Chia sẻ tài nguyên','Mối đe doạ','Tường lửa, VPN','Mã hoá','Ứng xử an toàn']))
S.append(S2(c,B+' · 1','Tài nguyên có thể chia sẻ',card('Các loại tài nguyên',ul(['<b>Dữ liệu</b>: tệp, thư mục, cơ sở dữ liệu.','<b>Thiết bị</b>: máy in, máy quét.','<b>Phần mềm</b> và <b>dịch vụ</b>.','<b>Đường truyền Internet</b>.'],6)),KEY('Mạng cho phép nhiều người <b>dùng chung</b> một tài nguyên, giảm chi phí và dễ quản lí.')))
S.append(S2(c,B+' · 1','Chia sẻ trong mạng LAN',card('Cách làm (Windows)',ul(['Chọn thư mục → <b>Share</b> / Chia sẻ.','Chọn người dùng và <b>quyền</b>: chỉ đọc hay đọc – ghi.','Người khác truy cập qua <b>\\\\tên-máy\\thư-mục</b>.'],6)),KEY('Cấp quyền theo nguyên tắc <b>tối thiểu</b>: chỉ <b>chỉ đọc</b> nếu người dùng chỉ cần xem.')+WARN('Không chia sẻ cả ổ đĩa hoặc thư mục chứa dữ liệu nhạy cảm cho mọi người.')))
S.append(TB(c,B+' · 1','Quyền khi chia sẻ tệp',['Quyền','Cho phép','Phù hợp'],[['<b>Chỉ đọc</b>','xem, sao chép','tài liệu học tập'],['<b>Đọc và ghi</b>','xem, sửa, thêm','nhóm cùng làm việc'],['<b>Toàn quyền</b>','cả xoá, đổi quyền','người quản lí'],['Không truy cập','—','người ngoài nhóm']],note=KEY('Chia sẻ máy in: máy in nối vào một máy hoặc nối trực tiếp mạng, mọi máy trong LAN <b>thêm máy in</b> rồi in.')))
S.append(S2(c,B+' · 1','Lưu trữ và chia sẻ qua đám mây',card('Đám mây (cloud)',ul(['Dữ liệu lưu trên <b>máy chủ của nhà cung cấp</b>.','Truy cập ở <b>mọi nơi, mọi thiết bị</b> có Internet.','Chia sẻ bằng <b>liên kết</b>, đặt quyền xem/sửa.','Ví dụ: Google Drive, OneDrive.'],6)),KEY('Ưu: tiện, đồng bộ, cộng tác. Nhược: cần Internet, <b>phụ thuộc nhà cung cấp</b>, lo ngại <b>riêng tư</b>.')))
S.append(TB(c,B+' · 1','Chia sẻ LAN và đám mây',['Tiêu chí','LAN','Đám mây'],[['Phạm vi','trong mạng nội bộ','mọi nơi có Internet'],['Chi phí','thiết bị riêng','thuê dịch vụ'],['Kiểm soát','<b>cao</b> (tự quản lí)','phụ thuộc nhà cung cấp'],['Sao lưu','tự lo','thường có sẵn']],note=KEY('Doanh nghiệp thường <b>kết hợp</b> cả hai tuỳ mức độ nhạy cảm của dữ liệu.')))
S.append(S2(c,B+' · 2','Các mối đe doạ an toàn mạng',card('Phân loại',ul(['<b>Mã độc</b>: virus, sâu, trojan, ransomware.','<b>Lừa đảo</b> (phishing), kĩ thuật xã hội.','<b>Tấn công từ chối dịch vụ</b> (DoS/DDoS).','<b>Nghe lén</b> dữ liệu, giả mạo (MITM).','<b>Dò mật khẩu</b>, khai thác lỗ hổng.'],6)),KEY('Ba mục tiêu cần bảo vệ (<b>CIA</b>): <b>bí mật</b>, <b>toàn vẹn</b>, <b>sẵn sàng</b>.')))
S.append(TB(c,B+' · 2','Mã độc thường gặp',['Loại','Đặc điểm'],[['<b>Virus</b>','gắn vào tệp, lây khi mở tệp'],['<b>Sâu (worm)</b>','tự lây lan qua mạng'],['<b>Trojan</b>','giả dạng phần mềm có ích'],['<b>Ransomware</b>','mã hoá dữ liệu, đòi tiền chuộc'],['<b>Spyware</b>','theo dõi, đánh cắp thông tin'],['<b>Botnet</b>','mạng máy bị điều khiển để tấn công']],note=KEY('Phòng chống: <b>cập nhật</b>, phần mềm diệt virus, <b>không mở tệp lạ</b>, <b>sao lưu</b>.')))
S.append(S2(c,B+' · 2','Tấn công từ chối dịch vụ (DDoS)',RES(svg(240,box(190,90,140,56,'Máy chủ','#FFCCBC','#D84315')+ln(60,30,190,100,'#D84315')+ln(60,100,190,115,'#D84315')+ln(60,180,190,130,'#D84315')+ln(460,30,330,100,'#D84315')+ln(460,120,330,118,'#D84315')+ln(460,190,330,135,'#D84315')+box(0,10,80,36,'Bot')+box(0,82,80,36,'Bot')+box(0,162,80,36,'Bot')+box(440,10,80,36,'Bot')+box(440,102,80,36,'Bot')+box(440,172,80,36,'Bot')),'DDoS'),card('Cách hoạt động',ul(['Hàng nghìn máy nhiễm mã độc (<b>botnet</b>) cùng gửi yêu cầu.','Máy chủ <b>quá tải</b>, người dùng thật không truy cập được.'],6))))
S.append(S2(c,B+' · 2','Lừa đảo (phishing)',card('Dấu hiệu nhận biết',ul(['Thư giả danh <b>ngân hàng, cơ quan</b>, doạ khoá tài khoản.','<b>Địa chỉ gửi, tên miền</b> lạ (vietcombank<b>-</b>secure.xyz).','Yêu cầu <b>mật khẩu, OTP</b>, bấm liên kết gấp.','Lỗi chính tả, văn phong lạ.'],6)),KEY('Cách phòng: <b>không bấm liên kết lạ</b>, tự gõ địa chỉ trang chính thức; <b>không bao giờ</b> cung cấp OTP cho người khác.')+WARN('Ngân hàng <b>không</b> hỏi mật khẩu hay OTP qua tin nhắn, điện thoại.')))
S.append(S2(c,B+' · 3','Tường lửa (firewall)',card('Khái niệm',ul(['Phần mềm hoặc thiết bị <b>lọc gói tin</b> vào – ra theo <b>quy tắc</b>.','Cho phép hoặc chặn theo <b>địa chỉ IP, cổng, giao thức</b>.'],6)),RES(svg(160,box(10,50,110,56,'Internet','#FFCCBC','#D84315')+box(200,40,120,76,'Tường lửa','#FFF9C4','#F9A825')+box(400,50,110,56,'LAN','#C8E6C9','#2E7D32')+ln(120,78,200,78)+ln(320,78,400,78)),'Vị trí tường lửa')))
S.append(TB(c,B+' · 3','Ví dụ quy tắc tường lửa',['Quy tắc','Nguồn','Cổng','Hành động'],[['1','bất kì','443 (HTTPS)','<b>cho phép</b>'],['2','bất kì','80 (HTTP)','<b>cho phép</b>'],['3','bất kì','23 (Telnet)','<b>chặn</b>'],['4','mạng nội bộ','22 (SSH)','cho phép'],['5','bất kì','mọi cổng','<b>chặn</b> (mặc định)']],note=KEY('Nguyên tắc: <b>chặn tất cả</b> rồi chỉ <b>cho phép</b> những gì cần thiết; quy tắc xét <b>từ trên xuống</b>.')))
S.append(S2(c,B+' · 3','Mã hoá dữ liệu',card('Khái niệm',ul(['<b>Mã hoá</b>: biến dữ liệu thành dạng <b>không đọc được</b> nếu không có khoá.','<b>Bản rõ</b> → (mã hoá + khoá) → <b>bản mã</b> → (giải mã + khoá) → bản rõ.'],6)),T(tr('Loại','Khoá','Đặc điểm',h=True)+tr('<b>Đối xứng</b>','một khoá chung','nhanh; khó trao đổi khoá')+tr('<b>Bất đối xứng</b>','khoá công khai + khoá bí mật','chậm hơn; an toàn khi trao khoá'))))
S.append(PYR(c,B+' · 3','Mã Caesar: mã hoá đơn giản','def ma_hoa(s, k):\n    kq = ""\n    for ch in s:\n        if ch.isalpha():\n            goc = ord("A")\n            kq += chr((ord(ch.upper()) - goc + k) % 26 + goc)\n        else:\n            kq += ch\n    return kq\nbm = ma_hoa("HELLO WORLD", 3)\nprint(bm)\nprint(ma_hoa(bm, -3))',KEY('Mỗi chữ cái <b>dịch k vị trí</b>; giải mã dịch ngược. Đây là mã <b>đối xứng</b> rất yếu (chỉ 25 khoá có thể thử hết).'),19))
S.append(S2(c,B+' · 3','HTTPS, chứng chỉ số và VPN',card('HTTPS',ul(['HTTP + <b>TLS</b>: mã hoá, xác thực máy chủ bằng <b>chứng chỉ số</b>.'],6))+card('VPN (mạng riêng ảo)',ul(['Tạo <b>đường hầm mã hoá</b> qua Internet.','Nối an toàn từ xa vào mạng cơ quan; che địa chỉ IP thật.'],6)),KEY('Dùng Wi-Fi công cộng: nên dùng <b>VPN</b> và chỉ vào trang <b>HTTPS</b>.')))
S.append(TB(c,B+' · 4','Bảo mật Wi-Fi gia đình',['Việc nên làm','Lý do'],[['Dùng chuẩn <b>WPA2/WPA3</b>','mã hoá đường truyền (tránh WEP, mạng mở)'],['Đặt <b>mật khẩu Wi-Fi mạnh</b>','chống người lạ dùng ké'],['Đổi mật khẩu quản trị router','mặc định dễ bị đoán'],['Cập nhật <b>phần mềm router</b>','vá lỗ hổng'],['Tắt WPS nếu không dùng','tránh dò mã PIN']],note=KEY('Tên Wi-Fi (SSID) không nên chứa thông tin cá nhân.')))
S.append(TB(c,B+' · 4','Ứng xử an toàn trên mạng',['Nên','Không nên'],[['Mật khẩu dài, khác nhau, bật <b>2FA</b>','dùng một mật khẩu cho mọi nơi'],['Kiểm tra <b>tên miền</b> trước khi nhập thông tin','bấm liên kết trong thư lạ'],['<b>Cập nhật</b> hệ điều hành, phần mềm','dùng phần mềm lậu, không rõ nguồn'],['<b>Sao lưu</b> dữ liệu quan trọng','chia sẻ thông tin cá nhân công khai'],['Đăng xuất khi dùng máy công cộng','nhập mật khẩu trên Wi-Fi công cộng không bảo vệ']],note=KEY('Nguyên tắc: <b>suy nghĩ trước khi bấm</b>; thông tin đã đăng lên mạng thường <b>khó xoá hẳn</b>.')))
S.append(S2(c,B+' · 4','Pháp luật và đạo đức khi dùng mạng',card('Quy định',ul(['<b>Luật An ninh mạng</b>, Luật An toàn thông tin mạng: cấm truy cập trái phép, phát tán mã độc, đưa tin sai sự thật.','Tôn trọng <b>bản quyền</b>, không xâm phạm quyền riêng tư.'],6)),KEY('Người dùng có trách nhiệm: <b>không phát tán</b> tin giả, không bắt nạt trên mạng; <b>báo cáo</b> nội dung xấu.')))
S+=END(c,B,['Chia sẻ tài nguyên: <b>LAN</b> (thư mục, máy in) và <b>đám mây</b> (liên kết).','Cấp quyền theo nguyên tắc <b>tối thiểu</b>.','Mối đe doạ: <b>mã độc, phishing, DDoS, nghe lén</b>.','<b>Tường lửa</b> lọc gói; <b>mã hoá</b> bảo vệ nội dung; <b>VPN</b> đường hầm an toàn.','Wi-Fi: dùng <b>WPA2/WPA3</b>, mật khẩu mạnh.'],[('Lọc gói tin','tường lửa'),('Nối an toàn từ xa','VPN'),('Lừa lấy mật khẩu','phishing'),('Đòi tiền chuộc','ransomware')],'Mở tệp, liên kết lạ; dùng chung một mật khẩu.',['Mã hoá <b>đối xứng</b> một khoá; <b>bất đối xứng</b> hai khoá.','Tường lửa <b>không chặn</b> được lừa đảo nếu người dùng tự bấm.','DDoS khác DoS: nhiều nguồn tấn công cùng lúc.','Ransomware: sao lưu <b>ngoài</b> máy là biện pháp tốt nhất.'],['<b>IDS/IPS</b>: hệ thống phát hiện, ngăn chặn xâm nhập.','<b>Chữ kí số</b> xác thực và đảm bảo toàn vẹn.','<b>Zero-trust</b>: không mặc định tin ai.'],
 [('Nêu hai cách chia sẻ tệp.',),('Phishing là gì? Nêu một dấu hiệu.',),('Tường lửa có chức năng gì?',),('Mã hoá đối xứng khác bất đối xứng ở điểm nào?',),('VPN dùng để làm gì?',)],
 [('Thư mục chia sẻ trong LAN; lưu và chia sẻ qua đám mây.',),('Lừa người dùng cung cấp thông tin; dấu hiệu: tên miền lạ, doạ khoá tài khoản.',),('Lọc gói tin vào – ra theo quy tắc.',),('Đối xứng: một khoá; bất đối xứng: cặp khoá công khai – bí mật.',),('Tạo đường hầm mã hoá, nối an toàn qua Internet.',)],
 [('Mã Caesar với khoá 3: mã hoá “CAT”.',),('Một thư báo “tài khoản bị khoá, nhập OTP tại liên kết”. Nên làm gì?',),('Đúng hay sai: (a) Tường lửa thay thế phần mềm diệt virus. (b) HTTPS mã hoá dữ liệu khi truyền. (c) Ransomware là mã độc đòi tiền chuộc. (d) Mã Caesar rất khó bẻ khoá.',),('Vì sao nên dùng VPN trên Wi-Fi công cộng?',),('Nên cấp quyền gì cho nhóm học sinh chỉ cần xem tài liệu của giáo viên?',),('Thứ tự thích hợp của các quy tắc tường lửa: “chặn tất cả”, “cho phép 443”?',)],
 [('Dịch 3 vị trí: C→<b>F</b>, A→<b>D</b>, T→<b>W</b>: “<b>FDW</b>”.',),('Không bấm liên kết, không đưa OTP; tự mở trang chính thức hoặc gọi tổng đài.',),('(a) <b>Sai</b>. (b) <b>Đúng</b>. (c) <b>Đúng</b>. (d) <b>Sai</b>: chỉ 25 khoá.',),('Mạng công cộng dễ bị nghe lén; VPN mã hoá đường truyền.',),('<b>Chỉ đọc</b>.',),('Đặt <b>“cho phép 443” trước</b>, “chặn tất cả” <b>sau cùng</b> (xét từ trên xuống).',)],hper=2)
